import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第九章 公司债券","description":"","frontmatter":{"title":"第九章 公司债券","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第九章：公司债券.md"},"headers":[],"relativePath":"blogs/CL/dijiuzhang：gongsizhaiquan.md","filePath":"blogs/CL/第九章：公司债券.md"}'),i={name:"blogs/CL/dijiuzhang：gongsizhaiquan.md"};function h(l,a,n,d,s,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="第九章-公司债券" tabindex="-1">第九章 公司债券 <a class="header-anchor" href="#第九章-公司债券" aria-label="Permalink to &quot;第九章 公司债券&quot;">​</a></h1><h3 id="第一百九十四条" tabindex="-1">第一百九十四条 <a class="header-anchor" href="#第一百九十四条" aria-label="Permalink to &quot;第一百九十四条&quot;">​</a></h3><p>四条本法所称公司债券，是指公司发行的约定按期还本付息的有价证券。 公司债券可以公开发行，也可以非公开发行。 公司债券的发行和交易应当符合《中华人民共和国证券法》等法律、行政法规的规定。</p><h3 id="第一百九十五条" tabindex="-1">第一百九十五条 <a class="header-anchor" href="#第一百九十五条" aria-label="Permalink to &quot;第一百九十五条&quot;">​</a></h3><p>五条公开发行公司债券，应当经国务院证券监督管理机构注册，公告公司债券募集办法。 公司债券募集办法应当载明下列主要事项： （一）公司名称； （二）债券募集资金的用途； （三）债券总额和债券的票面金额； （四）债券利率的确定方式； （五）还本付息的期限和方式； （六）债券担保情况； （七）债券的发行价格、发行的起止日期； （八）公司净资产额； （九）已发行的尚未到期的公司债券总额； （十）公司债券的承销机构。</p><h3 id="第一百九十六条" tabindex="-1">第一百九十六条 <a class="header-anchor" href="#第一百九十六条" aria-label="Permalink to &quot;第一百九十六条&quot;">​</a></h3><p>六条公司以纸面形式发行公司债券的，应当在债券上载明公司名称、债券票面金额、利率、偿还期限等事项，并由法定代表人签名，公司盖章。</p><h3 id="第一百九十七条" tabindex="-1">第一百九十七条 <a class="header-anchor" href="#第一百九十七条" aria-label="Permalink to &quot;第一百九十七条&quot;">​</a></h3><p>七条公司债券应当为记名债券。</p><h3 id="第一百九十八条" tabindex="-1">第一百九十八条 <a class="header-anchor" href="#第一百九十八条" aria-label="Permalink to &quot;第一百九十八条&quot;">​</a></h3><p>八条公司发行公司债券应当置备公司债券持有人名册。 发行公司债券的，应当在公司债券持有人名册上载明下列事项： （一）债券持有人的姓名或者名称及住所； （二）债券持有人取得债券的日期及债券的编号； （三）债券总额，债券的票面金额、利率、还本付息的期限和方式； （四）债券的发行日期。</p><h3 id="第一百九十九条" tabindex="-1">第一百九十九条 <a class="header-anchor" href="#第一百九十九条" aria-label="Permalink to &quot;第一百九十九条&quot;">​</a></h3><p>九条公司债券的登记结算机构应当建立债券登记、存管、付息、兑付等相关制度。</p><h3 id="第二百条" tabindex="-1">第二百条 <a class="header-anchor" href="#第二百条" aria-label="Permalink to &quot;第二百条&quot;">​</a></h3><p>百条公司债券可以转让，转让价格由转让人与受让人约定。 公司债券的转让应当符合法律、行政法规的规定。</p><h3 id="第二百零一条" tabindex="-1">第二百零一条 <a class="header-anchor" href="#第二百零一条" aria-label="Permalink to &quot;第二百零一条&quot;">​</a></h3><p>一条公司债券由债券持有人以背书方式或者法律、行政法规规定的其他方式转让；转让后由公司将受让人的姓名或者名称及住所记载于公司债券持有人名册。</p><h3 id="第二百零二条" tabindex="-1">第二百零二条 <a class="header-anchor" href="#第二百零二条" aria-label="Permalink to &quot;第二百零二条&quot;">​</a></h3><p>二条股份有限公司经股东会决议，或者经公司章程、股东会授权由董事会决议，可以发行可转换为股票的公司债券，并规定具体的转换办法。上市公司发行可转换为股票的公司债券，应当经国务院证券监督管理机构注册。 发行可转换为股票的公司债券，应当在债券上标明可转换公司债券字样，并在公司债券持有人名册上载明可转换公司债券的数额。</p><h3 id="第二百零三条" tabindex="-1">第二百零三条 <a class="header-anchor" href="#第二百零三条" aria-label="Permalink to &quot;第二百零三条&quot;">​</a></h3><p>三条发行可转换为股票的公司债券的，公司应当按照其转换办法向债券持有人换发股票，但债券持有人对转换股票或者不转换股票有选择权。法律、行政法规另有规定的除外。</p><h3 id="第二百零四条" tabindex="-1">第二百零四条 <a class="header-anchor" href="#第二百零四条" aria-label="Permalink to &quot;第二百零四条&quot;">​</a></h3><p>四条公开发行公司债券的，应当为同期债券持有人设立债券持有人会议，并在债券募集办法中对债券持有人会议的召集程序、会议规则和其他重要事项作出规定。债券持有人会议可以对与债券持有人有利害关系的事项作出决议。 除公司债券募集办法另有约定外，债券持有人会议决议对同期全体债券持有人发生效力。</p><h3 id="第二百零五条" tabindex="-1">第二百零五条 <a class="header-anchor" href="#第二百零五条" aria-label="Permalink to &quot;第二百零五条&quot;">​</a></h3><p>五条公开发行公司债券的，发行人应当为债券持有人聘请债券受托管理人，由其为债券持有人办理受领清偿、债权保全、与债券相关的诉讼以及参与债务人破产程序等事项。</p><h3 id="第二百零六条" tabindex="-1">第二百零六条 <a class="header-anchor" href="#第二百零六条" aria-label="Permalink to &quot;第二百零六条&quot;">​</a></h3><p>六条债券受托管理人应当勤勉尽责，公正履行受托管理职责，不得损害债券持有人利益。 受托管理人与债券持有人存在利益冲突可能损害债券持有人利益的，债券持有人会议可以决议变更债券受托管理人。 债券受托管理人违反法律、行政法规或者债券持有人会议决议，损害债券持有人利益的，应当承担赔偿责任。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',29)])])}const b=e(i,[["render",h]]);export{u as __pageData,b as default};
